                Assert.Equal(s.Stock + billets, apres);
                Assert.Equal(s.Compte with { Balance = s.Compte.Balance + billets.Value }, r.Account);
            }

            break;
    }

    if (r.Status != AtmStatus.Ok)
    {
        AssertRefus(r, r.Status, s, espion);
